from collections import Counter


def transform(grid):
    """Decode each 3x3 patch as its most common non-5 color."""
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3:
        raise ValueError("grid dimensions must be multiples of 3")
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            counts = Counter(
                grid[i][j]
                for i in range(r, r + 3)
                for j in range(c, c + 3)
                if grid[i][j] != 5
            )
            if not counts:
                raise ValueError("patch contains only background color 5")
            row.append(counts.most_common(1)[0][0])
        out.append(row)
    return out
